-- BE-4 W-SCHEMA (UNI-2610): dữ liệu dev/test, không phải tiêu chuẩn HSA.
-- HSA TASK_TYPE values are stable and fixed; questionbank dev seed references these codes.
ON CONFLICT (group_id, code_normalized) DO NOTHING;

UPDATE catalog.catalog_group SET last_value = GREATEST(last_value, 8) WHERE id = '00000000-0000-7000-8100-000000000006';

-- Hồ sơ bảy kỳ thi; seed dev/test vì EXAM có thể trống trên môi trường thật.
ON CONFLICT (exam_item_id) DO NOTHING;

-- One HSA draft loaded from HSA_FULL. Counts are dev test data, not the HSA standard.
ON CONFLICT (id) DO NOTHING;


-- One block ref per seeded group; NULL MAPID is unlimited and is not inherited from a section.
ON CONFLICT (id) DO NOTHING;
